-- Moodle_api_project_DB v2.2

-- Note:
-- Enforce UNIQUE on all external Moodle record IDs, with
-- the exception of:
-- 1) sessions.moodle_attendance_id
-- 2) grades.moodle_grade_item_id
--
-- Also: enforce UNIQUE composite constraints on 'grades'
-- and 'attendance' tables (see below).

CREATE TYPE "attendance_status" AS ENUM (
  'present',
  'late',
  'absent',
  'excused'
);

-- Maps to Moodle "Course Categories"
CREATE TABLE "departments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(255) NOT NULL,
  "moodle_category_id" bigint UNIQUE NOT NULL
);

CREATE TABLE "courses" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "moodle_course_id" bigint UNIQUE NOT NULL,
  "fullname" varchar(255) NOT NULL,
  "shortname" varchar(255) NOT NULL,
  "department_id" bigint NOT NULL
);

-- aka "academic cohorts"
CREATE TABLE "groups" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "moodle_group_id" bigint UNIQUE NOT NULL,
  "name" varchar(255) NOT NULL,
  "course_id" bigint NOT NULL
);

-- Conceptually an Enrollment record.
--
-- Note: Students without Groups (Edge Case).
-- In Moodle, a user can be enrolled in a course
-- but not assigned to a group. So we need to
-- allow group_id to be nullable here.
CREATE TABLE "students" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "moodle_user_id" bigint UNIQUE NOT NULL,
  "first_name" varchar(255) NOT NULL,
  "last_name" varchar(255) NOT NULL,
  "group_id" bigint -- Nullable for ungrouped students
);

-- aka lectures
CREATE TABLE "sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "moodle_session_id" bigint UNIQUE NOT NULL,
  "moodle_attendance_id" bigint NOT NULL,
  "title" varchar(255) NOT NULL,
  "session_date" timestamptz NOT NULL,
  "group_id" bigint NOT NULL
);

CREATE TABLE "attendance" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "student_id" bigint NOT NULL,
  "session_id" bigint NOT NULL,
  "status" "attendance_status" NOT NULL,

  -- FIXED: Added the missing composite unique constraint
  CONSTRAINT uq_attendance_student_session UNIQUE ("student_id", "session_id")
);

CREATE TABLE "grades" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "moodle_grade_item_id" bigint NOT NULL,
  "course_id" bigint NOT NULL, -- FIXED: Using internal course_id instead of moodle_course_id
  "student_id" bigint NOT NULL,
  "item_name" varchar(255) NOT NULL,
  "points" decimal(10,2), -- If a student has not yet submitted an assignment, 'graderaw' will be null
  "date_graded" timestamptz NOT NULL,

  -- FIXED: Added the missing composite unique constraint
  CONSTRAINT uq_grades_student_item UNIQUE ("student_id", "moodle_grade_item_id")
);

-- ==========================================
-- FOREIGN KEYS
-- ==========================================
ALTER TABLE "courses" ADD FOREIGN KEY ("department_id") REFERENCES "departments" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "groups" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "students" ADD FOREIGN KEY ("group_id") REFERENCES "groups" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "sessions" ADD FOREIGN KEY ("group_id") REFERENCES "groups" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "attendance" ADD FOREIGN KEY ("student_id") REFERENCES "students" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "attendance" ADD FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") DEFERRABLE INITIALLY IMMEDIATE;

-- FIXED: Now references courses(id)
ALTER TABLE "grades" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "grades" ADD FOREIGN KEY ("student_id") REFERENCES "students" ("id") DEFERRABLE INITIALLY IMMEDIATE;

-- ================================================
-- PERFORMANCE INDEXES (Crucial for Data Warehouse)
-- ================================================
-- PostgreSQL does not auto-index FKs. Add these for fast joins:
CREATE INDEX idx_courses_department_id ON "courses"("department_id");
CREATE INDEX idx_groups_course_id ON "groups"("course_id");
CREATE INDEX idx_students_group_id ON "students"("group_id");
CREATE INDEX idx_sessions_group_id ON "sessions"("group_id");
CREATE INDEX idx_sessions_moodle_attendance_id ON "sessions"("moodle_attendance_id");
CREATE INDEX idx_attendance_student_id ON "attendance"("student_id");
CREATE INDEX idx_attendance_session_id ON "attendance"("session_id");
CREATE INDEX idx_grades_course_id ON "grades"("course_id");
CREATE INDEX idx_grades_student_id ON "grades"("student_id");
